import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-010 — Each Explore ruler regime gets its own best science card, no repeats within a ruler","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-010-ruler-regimes-each-get-their-own-science-card.md","filePath":"uxs/decisions/UXD-010-ruler-regimes-each-get-their-own-science-card.md"}'),s={name:"uxs/decisions/UXD-010-ruler-regimes-each-get-their-own-science-card.md"};function o(n,e,c,l,d,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="uxd-010-—-each-explore-ruler-regime-gets-its-own-best-science-card-no-repeats-within-a-ruler" tabindex="-1">UXD-010 — Each Explore ruler regime gets its own best science card, no repeats within a ruler <a class="header-anchor" href="#uxd-010-—-each-explore-ruler-regime-gets-its-own-best-science-card-no-repeats-within-a-ruler" aria-label="Permalink to &quot;UXD-010 — Each Explore ruler regime gets its own best science card, no repeats within a ruler&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-11 (the operator&#39;s point and clarification, then the go)</li><li><strong>Decider</strong>: the operator raised O6 (&quot;all orbit panes repeat the same science links … variety, different per pane, best matches, no repetition&quot;, <code>docs/wip/2026-11-11-ux-feedback-plan.md</code> line 177) and showed the GIANTS pane (lines 445–450). &quot;Slice B2 gives every regime its own best match, no repeats within a ruler&quot; is the lead&#39;s resolution under &quot;Answers (2026-11-11)&quot;. The operator, 2026-11-11 (session go after the UXD check), recorded in <code>docs/wip/2026-11-11-ux-feedback-plan.md</code>, line starting &quot;- Operator go, 2026-11-11 (session&quot; (line 460): the fixes for W6, SN2, G5/G6 and O6 &quot;are accepted as decided&quot;.</li><li><strong>Answers</strong>: O6, S1, S2; slice B2 (science links)</li><li><strong>Changes</strong>: UXS-014 / UXS-016 (no ruler section exists today; see UXS-000 §Next). The cap of five science links per panel (S2) is part of the same slice.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>On <code>/explore?regime=GIANTS</code> the pane&#39;s one science card is &quot;Planetary stats&quot;, the same as TERRESTRIAL. Across the Explore ruler <code>keplers-laws</code>, <code>apsides</code> and <code>hill-sphere</code> also repeat. The regime data (<code>science_link</code> per <code>orbit-regimes-explore/*</code> entry in <code>static/data/i18n/en-US.core.json</code>, read at <code>9fdf4cc4a6b</code>) holds: SUN <code>scales-time/light-minute</code>; TERRESTRIAL and GIANTS <code>planets/planetary-stats</code>; BELT and KUIPER <code>orbits/keplers-laws</code>; HELIOPAUSE and OORT <code>orbits/hill-sphere</code>; SCATTERED <code>orbits/apsides</code>. No regime links <code>light-year</code>. The operator remembered a &quot;light minute / light year&quot; pair (plan lines 445–448); the data confirms light-minute on SUN only. The plan&#39;s note that the regime data has neither is wrong about light-minute.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>The sources record one rule and no alternatives.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Every ruler regime gets its own best-matching science card, and no card repeats within one ruler.</strong> Pane links vary per pane.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Slice B2 also caps every panel at five science links and replaces the generic defaults and the MissionPanel push-chain (up to about 21 cards) with a ranked pick by type and phase (plan line 339).</li><li>The orbit ruler&#39;s other issues from the same screen belong to other slices: wrapping rows (C4), unlinked founding missions and the country codes (C5; both done in <a href="./UXD-024-orbit-ruler-one-row-draws-its-regime">UXD-024</a>), the close X drawn over scrolled text (B1), the Vega pill (C3).</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Written in slice B2 (<a href="./UXD-022-science-link-lists">UXD-022</a>): <code>src/lib/science-links.test.ts</code> (rulers: every pane has a card and none repeats inside its ruler, in the four ruler directories; locale parity) and <code>tests/e2e/science-links-cap.spec.ts</code> (the eight Explore panes show one card each, all different).</p>',12)])])}const g=t(s,[["render",o]]);export{u as __pageData,g as default};
